# -*- coding: utf-8 -*-
"""Генерирует config/bank.json — стартовый банк реплик Миры.

Это черновик: команда переписывает ответы своими словами и добавляет новые темы.
Шаблоны (patterns) — регулярные выражения по нормализованному тексту вопроса:
нижний регистр, «ё» заменена на «е». Порядок важен: первые темы проверяются раньше.
after — тема срабатывает только если одна из этих тем была в последних двух ходах.
"""
import json
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from team_bank import TEAM
from hall_bank import HALL

B = r"\b"
I = []


LOW = {"scared_new", "tired", "sad", "happy", "weather", "movies", "books", "games", "social", "greet_any", "walk",
       "music_user", "laundry", "football", "trip_rain", "pet_mischief", "hate_food", "brother_says", "many_say"}


def intent(id, patterns, answers, *, topic=None, after=None, not_=None, turn=None, priority=None):
    item = {"id": id, "topic": topic or id.split("_")[0], "patterns": patterns, "answers": answers}
    if priority is None and id in LOW:
        priority = -1
    if priority:
        item["priority"] = priority
    if after:
        item["after"] = after
    if not_:
        item["not"] = not_
    if turn is not None:
        item["turn"] = turn
    I.append(item)


