for it in HALL + TEAM + I:  # questions are matched after ё→е, so patterns must use е too
    it["patterns"] = [x.replace("ё", "е").replace("Ё", "Е") for x in it["patterns"]]
    if "not" in it:
        it["not"] = [x.replace("ё", "е") for x in it["not"]]

